META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–6: ಸಂನ್ಯಾಸ ಮತ್ತು ಕರ್ಮಯೋಗ ಎರಡೂ ಒಂದೇ ಗುರಿಗೆ ಒಯ್ಯುತ್ತವೆ, ಕರ್ಮಯೋಗ ಸುಲಭ; 7–12: ಯೋಗಿ ಕರ್ಮ ಮಾಡುತ್ತಾನೆ ಆದರೆ ಅಂಟಿಕೊಳ್ಳುವುದಿಲ್ಲ, ಕಮಲದ ಎಲೆಯಂತೆ; 13–17: ಆತ್ಮ ಕರ್ತನೂ ಅಲ್ಲ, ಪಾಪಪುಣ್ಯಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುವುದೂ ಇಲ್ಲ; 18–26: ಸಮದರ್ಶಿ ಜ್ಞಾನಿ ಮತ್ತು ಒಳಗಿನ ಆನಂದ; 27–29: ಧ್ಯಾನದ ಮೊದಲ ಸೂಚನೆ ಮತ್ತು ಶಾಂತಿಯ ಮೂಲ.',
)
T = {
1: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಕೃಷ್ಣ, ನೀವು ಕರ್ಮಗಳ ಸಂನ್ಯಾಸವನ್ನು ಹೊಗಳುತ್ತೀರಿ, ಮತ್ತೆ ಯೋಗವನ್ನೂ ಹೊಗಳುತ್ತೀರಿ. ಇವೆರಡರಲ್ಲಿ ಯಾವುದು ಶ್ರೇಷ್ಠವೋ ಅದೊಂದನ್ನೇ ನಿಶ್ಚಯವಾಗಿ ನನಗೆ ಹೇಳಿ.',
2: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಸಂನ್ಯಾಸ ಮತ್ತು ಕರ್ಮಯೋಗ ಎರಡೂ ಪರಮ ಶ್ರೇಯಸ್ಸನ್ನು ಕೊಡುತ್ತವೆ. ಆದರೆ ಅವೆರಡರಲ್ಲಿ ಕರ್ಮಸಂನ್ಯಾಸಕ್ಕಿಂತ ಕರ್ಮಯೋಗ ಶ್ರೇಷ್ಠ.',
3: 'ಹೇ ಮಹಾಬಾಹು, ದ್ವೇಷಿಸದ, ಬಯಸದವನನ್ನು ನಿತ್ಯ ಸಂನ್ಯಾಸಿ ಎಂದು ತಿಳಿ. ದ್ವಂದ್ವಗಳಿಂದ ಮುಕ್ತನಾದವನು ಸುಲಭವಾಗಿ ಬಂಧನದಿಂದ ಬಿಡುಗಡೆ ಹೊಂದುತ್ತಾನೆ.',
4: 'ಸಾಂಖ್ಯ ಮತ್ತು ಯೋಗ ಬೇರೆ ಬೇರೆ ಎಂದು ಹೇಳುವವರು ಬಾಲಕರು, ಪಂಡಿತರಲ್ಲ. ಒಂದರಲ್ಲಿ ಚೆನ್ನಾಗಿ ನೆಲೆಸಿದವನು ಎರಡರ ಫಲವನ್ನೂ ಪಡೆಯುತ್ತಾನೆ.',
5: 'ಸಾಂಖ್ಯರು ಯಾವ ಸ್ಥಾನವನ್ನು ಪಡೆಯುತ್ತಾರೋ ಅದನ್ನು ಯೋಗಿಗಳೂ ಪಡೆಯುತ್ತಾರೆ. ಸಾಂಖ್ಯ ಮತ್ತು ಯೋಗ ಒಂದೇ ಎಂದು ಕಾಣುವವನೇ ನಿಜವಾಗಿ ಕಾಣುತ್ತಾನೆ.',
6: 'ಆದರೆ ಹೇ ಮಹಾಬಾಹು, ಯೋಗವಿಲ್ಲದೆ ಸಂನ್ಯಾಸವನ್ನು ಪಡೆಯುವುದು ಕಷ್ಟ. ಯೋಗದಲ್ಲಿ ತೊಡಗಿದ ಮುನಿ ಬೇಗನೆ ಬ್ರಹ್ಮವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
7: 'ಯೋಗದಲ್ಲಿ ತೊಡಗಿದ, ಶುದ್ಧ ಮನಸ್ಸಿನ, ತನ್ನನ್ನು ಗೆದ್ದ, ಇಂದ್ರಿಯಗಳನ್ನು ಗೆದ್ದ, ಎಲ್ಲ ಜೀವಿಗಳ ಆತ್ಮವೇ ತನ್ನ ಆತ್ಮವಾದವನು ಕರ್ಮ ಮಾಡಿದರೂ ಅಂಟಿಕೊಳ್ಳುವುದಿಲ್ಲ.',
8: 'ತತ್ತ್ವವನ್ನು ತಿಳಿದ ಯೋಗಿ ನೋಡುತ್ತಾ, ಕೇಳುತ್ತಾ, ಮುಟ್ಟುತ್ತಾ, ಮೂಸುತ್ತಾ, ತಿನ್ನುತ್ತಾ, ನಡೆಯುತ್ತಾ, ಮಲಗುತ್ತಾ, ಉಸಿರಾಡುತ್ತಾ "ನಾನು ಏನನ್ನೂ ಮಾಡುತ್ತಿಲ್ಲ" ಎಂದು ತಿಳಿಯುತ್ತಾನೆ,',
9: 'ಮಾತನಾಡುತ್ತಾ, ಬಿಡುತ್ತಾ, ಹಿಡಿಯುತ್ತಾ, ಕಣ್ಣು ತೆರೆಯುತ್ತಾ ಮುಚ್ಚುತ್ತಾ, "ಇಂದ್ರಿಯಗಳು ತಮ್ಮ ವಿಷಯಗಳಲ್ಲಿ ವರ್ತಿಸುತ್ತಿವೆ" ಎಂದು ಭಾವಿಸುತ್ತಾನೆ.',
11: 'ಯೋಗಿಗಳು ಆತ್ಮಶುದ್ಧಿಗಾಗಿ ಆಸಕ್ತಿಯನ್ನು ಬಿಟ್ಟು ದೇಹದಿಂದ, ಮನಸ್ಸಿನಿಂದ, ಬುದ್ಧಿಯಿಂದ ಮತ್ತು ಕೇವಲ ಇಂದ್ರಿಯಗಳಿಂದ ಕರ್ಮ ಮಾಡುತ್ತಾರೆ.',
12: 'ಯೋಗದಲ್ಲಿ ತೊಡಗಿದವನು ಕರ್ಮಫಲವನ್ನು ತ್ಯಜಿಸಿ ಸ್ಥಿರವಾದ ಶಾಂತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ. ಯೋಗವಿಲ್ಲದವನು ಕಾಮನೆಯಿಂದ ಫಲದಲ್ಲಿ ಆಸಕ್ತನಾಗಿ ಬಂಧಿಸಲ್ಪಡುತ್ತಾನೆ.',
13: 'ಸಂಯಮಿಯಾದ ದೇಹಧಾರಿ ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ಮನಸ್ಸಿನಿಂದ ತ್ಯಜಿಸಿ, ಒಂಬತ್ತು ಬಾಗಿಲುಗಳ ನಗರದಲ್ಲಿ (ದೇಹದಲ್ಲಿ) ಏನನ್ನೂ ಮಾಡದೆ, ಮಾಡಿಸದೆ ಸುಖವಾಗಿ ನೆಲೆಸುತ್ತಾನೆ.',
14: 'ಪ್ರಭು (ಆತ್ಮ) ಲೋಕದ ಕರ್ತೃತ್ವವನ್ನಾಗಲಿ ಕರ್ಮಗಳನ್ನಾಗಲಿ ಕರ್ಮಫಲದ ಸಂಯೋಗವನ್ನಾಗಲಿ ಸೃಷ್ಟಿಸುವುದಿಲ್ಲ. ಸ್ವಭಾವವೇ (ಪ್ರಕೃತಿಯೇ) ಇವುಗಳಲ್ಲಿ ವರ್ತಿಸುತ್ತದೆ.',
15: 'ಸರ್ವವ್ಯಾಪಿ ಯಾರ ಪಾಪವನ್ನೂ ಪುಣ್ಯವನ್ನೂ ತೆಗೆದುಕೊಳ್ಳುವುದಿಲ್ಲ. ಅಜ್ಞಾನದಿಂದ ಜ್ಞಾನ ಮುಚ್ಚಿಹೋಗಿದೆ, ಅದರಿಂದ ಜೀವಿಗಳು ಮೋಹಗೊಳ್ಳುತ್ತವೆ.',
16: 'ಆದರೆ ಯಾರ ಅಜ್ಞಾನ ಆತ್ಮಜ್ಞಾನದಿಂದ ನಾಶವಾಗಿದೆಯೋ, ಅವರ ಜ್ಞಾನ ಸೂರ್ಯನಂತೆ ಪರಮತತ್ತ್ವವನ್ನು ಬೆಳಗುತ್ತದೆ.',
17: 'ಅದರಲ್ಲಿ ಬುದ್ಧಿ ನೆಲೆಸಿ, ಅದೇ ಆತ್ಮವಾಗಿ, ಅದರಲ್ಲೇ ನಿಷ್ಠೆಯಿಟ್ಟು, ಅದನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಹೊಂದಿದವರು ಜ್ಞಾನದಿಂದ ಪಾಪಗಳು ತೊಳೆದುಹೋಗಿ, ಮತ್ತೆ ಹಿಂತಿರುಗದ ಸ್ಥಾನವನ್ನು ಸೇರುತ್ತಾರೆ.',
19: 'ಯಾರ ಮನಸ್ಸು ಸಮತ್ವದಲ್ಲಿ ನೆಲೆಸಿದೆಯೋ ಅವರು ಈ ಲೋಕದಲ್ಲೇ ಸಂಸಾರವನ್ನು ಗೆದ್ದಿದ್ದಾರೆ. ಬ್ರಹ್ಮ ದೋಷರಹಿತ ಮತ್ತು ಸಮ; ಆದ್ದರಿಂದ ಅವರು ಬ್ರಹ್ಮದಲ್ಲಿ ನೆಲೆಸಿದ್ದಾರೆ.',
20: 'ಪ್ರಿಯವಾದುದು ಸಿಕ್ಕಾಗ ಹಿಗ್ಗದ, ಅಪ್ರಿಯವಾದುದು ಸಿಕ್ಕಾಗ ಕುಗ್ಗದ, ಸ್ಥಿರಬುದ್ಧಿಯ, ಮೋಹವಿಲ್ಲದ ಬ್ರಹ್ಮಜ್ಞಾನಿ ಬ್ರಹ್ಮದಲ್ಲಿ ನೆಲೆಸಿದ್ದಾನೆ.',
21: 'ಹೊರಗಿನ ಸ್ಪರ್ಶಗಳಲ್ಲಿ ಆಸಕ್ತಿಯಿಲ್ಲದವನು ತನ್ನೊಳಗೆ ಇರುವ ಸುಖವನ್ನು ಪಡೆಯುತ್ತಾನೆ. ಬ್ರಹ್ಮಯೋಗದಲ್ಲಿ ತೊಡಗಿದ ಅವನು ಅಕ್ಷಯ ಸುಖವನ್ನು ಅನುಭವಿಸುತ್ತಾನೆ.',
22: 'ಹೇ ಕೌಂತೇಯ, ಸ್ಪರ್ಶದಿಂದ ಹುಟ್ಟುವ ಭೋಗಗಳು ದುಃಖದ ಮೂಲಗಳೇ; ಅವಕ್ಕೆ ಆದಿ ಮತ್ತು ಅಂತ್ಯ ಇದೆ. ಜ್ಞಾನಿ ಅವುಗಳಲ್ಲಿ ರಮಿಸುವುದಿಲ್ಲ.',
23: 'ದೇಹವನ್ನು ಬಿಡುವ ಮುಂಚೆಯೇ ಇಲ್ಲಿಯೇ ಕಾಮ ಮತ್ತು ಕ್ರೋಧದಿಂದ ಹುಟ್ಟುವ ವೇಗವನ್ನು ಸಹಿಸಬಲ್ಲವನು ಯೋಗಿ, ಅವನೇ ಸುಖಿ.',
24: 'ಒಳಗೆ ಸುಖವುಳ್ಳ, ಒಳಗೆ ರಮಿಸುವ, ಒಳಗೆ ಬೆಳಕುಳ್ಳ ಯೋಗಿ ಬ್ರಹ್ಮರೂಪನಾಗಿ ಬ್ರಹ್ಮನಿರ್ವಾಣವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
25: 'ಪಾಪಗಳು ನಾಶವಾದ, ಸಂಶಯಗಳು ಕತ್ತರಿಸಿಹೋದ, ತನ್ನನ್ನು ಗೆದ್ದ, ಎಲ್ಲ ಜೀವಿಗಳ ಹಿತದಲ್ಲಿ ಆನಂದಿಸುವ ಋಷಿಗಳು ಬ್ರಹ್ಮನಿರ್ವಾಣವನ್ನು ಪಡೆಯುತ್ತಾರೆ.',
26: 'ಕಾಮ ಮತ್ತು ಕ್ರೋಧದಿಂದ ಮುಕ್ತರಾದ, ಮನಸ್ಸನ್ನು ಗೆದ್ದ, ಆತ್ಮವನ್ನು ತಿಳಿದ ಯತಿಗಳಿಗೆ ಎಲ್ಲೆಡೆಯೂ ಬ್ರಹ್ಮನಿರ್ವಾಣ ಇರುತ್ತದೆ.',
27: 'ಹೊರಗಿನ ಸ್ಪರ್ಶಗಳನ್ನು ಹೊರಗೇ ಇಟ್ಟು, ದೃಷ್ಟಿಯನ್ನು ಹುಬ್ಬುಗಳ ನಡುವೆ ನಿಲ್ಲಿಸಿ, ಮೂಗಿನೊಳಗೆ ಚಲಿಸುವ ಪ್ರಾಣ ಮತ್ತು ಅಪಾನವನ್ನು ಸಮಗೊಳಿಸಿ,',
28: 'ಇಂದ್ರಿಯ, ಮನಸ್ಸು ಮತ್ತು ಬುದ್ಧಿಯನ್ನು ನಿಯಂತ್ರಿಸಿದ, ಮೋಕ್ಷವನ್ನೇ ಗುರಿಯಾಗಿಸಿಕೊಂಡ, ಬಯಕೆ, ಭಯ ಮತ್ತು ಕ್ರೋಧ ಹೋದ ಮುನಿ ಸದಾ ಮುಕ್ತನೇ.',
29: 'ನನ್ನನ್ನು ಯಜ್ಞ ಮತ್ತು ತಪಸ್ಸುಗಳ ಭೋಕ್ತನೆಂದು, ಎಲ್ಲ ಲೋಕಗಳ ಮಹೇಶ್ವರನೆಂದು, ಎಲ್ಲ ಜೀವಿಗಳ ಸ್ನೇಹಿತನೆಂದು ತಿಳಿದು ಅವನು ಶಾಂತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
}
